/* EVALUX · pantallas del docente */
const misEx=()=>S.examenes.filter(e=>e.docente===S.yo.id);
const misGrupos=()=>S.grupos.filter(g=>g.docente===S.yo.id);
const nEst=e=>new Set(e.grupos.flatMap(g=>(S.grupos.find(x=>x.id===g)||{est:[]}).est)).size;
const estDe=id=>S.estudiantes.find(x=>x.id===id)||{id,nombre:'Estudiante retirado',correo:'',codigo:'—',prog:'',fac:'',semestre:''};
const grupoTxt=id=>{const g=S.grupos.find(x=>x.id===id);return g?`${g.asig} · Grupo ${g.codigo}`:''};
function stats(e){const filas=Object.keys(S.intentos).filter(k=>k.startsWith(e.id+'|')).map(k=>({s:estDe(k.split('|')[1]),...S.intentos[k]})).filter(f=>f.nota!=null&&f.estado==='entregado');
 const sos=Object.keys(S.intentos).filter(k=>k.startsWith(e.id+'|')&&S.intentos[k].estado==='sospecha').map(k=>({s:estDe(k.split('|')[1]),...S.intentos[k]}));
 const n=filas.length,prom=n?filas.reduce((a,f)=>a+f.nota,0)/n:0,aprob=filas.filter(f=>f.nota>=S.cfg.aprueba).length;
 const porPreg=e.preg.map(q=>{let ok=0;const dist=q.tipo==='sel'?q.opts.map(()=>0):null;filas.forEach(f=>{const r=f.respuestas[q.id];ok+=puntaje(q,r,f);if(dist&&r!=null&&dist[r]!=null)dist[r]++});return{q,pct:n?ok/n*100:0,dist}});
 return{filas,sos,n,prom,aprob,porPreg}}
const tieneImg=e=>e.preg.some(q=>(q.imgs||[]).length||(q.optImgs||[]).some(Boolean)||(q.parImgs||[]).some(Boolean));
function ticket(e,acts){const st=estadoExamen(e),d=e.apertura?new Date(e.apertura):null;
 return `<article class="ticket" style="--tk:${TK_EX[st]}"><div class="date">${d?`<span class="d">${d.getDate()}</span><span class="m">${mes(d)}</span><span class="h">${hora(d)}</span>`:`<span class="d">${ic('edit')}</span><span class="m">Borrador</span>`}</div>
 <div class="info"><div class="row" style="gap:8px"><span class="chip">${esc(e.asig)}</span><span class="pill ${PILL_EX[st]}"><i></i>${cap(st)}</span>${bloqueado(e)?`<span class="pill p-mute" title="Ya fue presentado">${ic('lock','sm')}Bloqueado</span>`:''}</div>
 <h3>${esc(e.titulo)}</h3><div class="meta"><span>${ic('exam','sm')}${e.preg.length} pregunta${e.preg.length===1?'':'s'}</span><span>${ic('clock','sm')}${e.dur} min</span><span>${ic('group','sm')}${e.grupos.map(g=>'Grupo '+esc((S.grupos.find(x=>x.id===g)||{}).codigo||'')).join(', ')||'Sin grupo'}</span>${tieneImg(e)?`<span>${ic('image','sm')}Con imágenes</span>`:''}</div>
 <div class="row" style="gap:6px;margin-top:2px">${acts}</div></div></article>`}
function semana(){const dias=[...Array(7)].map((_,i)=>{const d=ahora();d.setHours(0,0,0,0);return addMin(d,i*1440)});
 return `<div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px">${dias.map((d,i)=>{const ex=misEx().filter(e=>e.apertura&&new Date(e.apertura).toDateString()===d.toDateString());return `<div style="border:1px solid var(--line);border-radius:14px;padding:8px 4px;text-align:center;background:${i===0?'var(--brand-soft)':'var(--surface-2)'};min-width:0"><div class="small muted" style="text-transform:capitalize">${d.toLocaleDateString('es-CO',{weekday:'short'}).replace('.','')}</div><b style="font-size:1.2rem">${d.getDate()}</b><div style="display:flex;gap:3px;justify-content:center;margin-top:4px;min-height:8px">${ex.map(e=>`<i title="${esc(e.titulo)}" style="width:8px;height:8px;border-radius:50%;background:${TK_EX[estadoExamen(e)]}"></i>`).join('')}</div></div>`}).join('')}</div>`}
function vDocInicio(){const d=doc(),ex=misEx(),enCurso=ex.filter(e=>estadoExamen(e)==='en curso'),prox=ex.filter(e=>estadoExamen(e)==='programado').sort((a,b)=>new Date(a.apertura)-new Date(b.apertura)),cer=ex.filter(e=>estadoExamen(e)==='cerrado').sort((a,b)=>new Date(b.apertura)-new Date(a.apertura)),c=cer[0],r=c?stats(c):null;
 const g0=misGrupos()[0],gl=g0?cer.filter(e=>e.grupos.includes(g0.id)).slice().reverse():[];
 const pasos=[[misGrupos().length>0,'Cree un grupo','grupos'],[misGrupos().some(g=>g.est.length),'Agregue estudiantes','grupos'],[ex.length>0,'Cree su primer examen','examenes']];
 return `${hero('Docente','Hola, '+esc(d.nombres.split(' ')[0]),'Sus asignaturas: '+d.asig.map(esc).join(' · '),`<button class="btn pri" data-act="ex-new">${ic('plus','sm')}Crear examen</button><button class="btn" data-act="nav" data-v="reportes">${ic('chart','sm')}Reportes</button>`,'edit')}
 ${pasos.some(p=>!p[0])?`<div class="card" style="display:flex;flex-direction:column;gap:12px;border-left:6px solid var(--brand)"><h3>Para empezar</h3><div class="grid2" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">${pasos.map(([ok,t,v],i)=>`<button class="card row" data-act="nav" data-v="${v}" style="all:unset;cursor:pointer;display:flex;gap:12px;align-items:center;padding:14px;border:1px solid var(--line);border-radius:16px;background:${ok?'var(--ok-soft)':'var(--surface-2)'}"><span class="q-n" style="background:${ok?'var(--ok)':'var(--brand)'}">${ok?'✓':i+1}</span><b>${t}</b></button>`).join('')}</div></div>`:''}
 ${enCurso.map(e=>`<div class="card" style="display:flex;gap:18px;align-items:center;flex-wrap:wrap;border:2px solid var(--coral)">${ring(presentados(e)/Math.max(1,nEst(e)),'var(--coral)',86,10,presentados(e)+'/'+nEst(e))}<div style="flex:1 1 240px;min-width:0"><span class="pill p-hot live"><i></i>En curso ahora</span><h3 style="margin-top:8px">${esc(e.titulo)}</h3><p class="small muted">Termina para todos a las ${hora(cierre(e))} · han entrado ${presentados(e)} de ${nEst(e)} estudiantes</p></div><button class="btn hot" data-act="ex-sala" data-id="${e.id}">${ic('eye','sm')}Abrir sala en vivo</button></div>`).join('')}
 <div class="bento">${tile('group','c1','Grupos',misGrupos().length,misGrupos().reduce((a,g)=>a+g.est.length,0)+' estudiantes')}${tile('exam','c2','Exámenes',ex.length,ex.filter(e=>estadoExamen(e)==='borrador').length+' en borrador')}${tile('bank','c4','Banco de preguntas',S.banco.length,'listas para reutilizar')}${r&&r.n?tile('trend','cok','Último promedio',nota1(r.prom),r.aprob+' de '+r.n+' aprobaron'):tile('trend','cok','Último promedio','—','aún sin exámenes cerrados')}
 <div class="card s7"><div class="card-h"><span class="chipi cb">${ic('cal')}</span><h3>Esta semana</h3></div>${semana()}<div class="legend" style="margin-top:12px"><span style="--c:#E0562F">En curso</span><span style="--c:#2B3A8C">Programado</span><span style="--c:#1F7A4D">Cerrado</span></div></div>
 <div class="card s5"><div class="card-h"><span class="chipi c3">${ic('trend')}</span><h3>Evolución${g0?' · '+esc(g0.asig)+' '+esc(g0.codigo):''}</h3></div>${gl.length?linea([{n:'Promedio del grupo',c:'var(--brand)',v:gl.map(e=>stats(e).prom)}],gl.map(e=>fcorta(e.apertura)),{h:210}):'<p class="muted">Aparece cuando tenga exámenes cerrados.</p>'}</div></div>
 ${prox.length||c?`<h2>Próximos y recientes</h2><div class="grid2">${prox.slice(0,2).map(e=>ticket(e,bloqueado(e)?'':`<button class="btn sm" data-act="ex-edit" data-id="${e.id}">${ic('edit','sm')}Editar</button>`)).join('')}${c?ticket(c,`<button class="btn sm pri" data-act="ex-res" data-id="${c.id}">${ic('chart','sm')}Ver resultados</button>`):''}</div>`:''}`}

/* ---------- grupos ---------- */
function vGrupos(){const gs=misGrupos();if(!S.grupoSel||!gs.find(g=>g.id===S.grupoSel))S.grupoSel=gs[0]&&gs[0].id;const g=gs.find(x=>x.id===S.grupoSel),q=norm(S.fEst||'');
 const ests=g?g.est.map(estDe).filter(s=>!q||norm(s.nombre+' '+s.codigo+' '+s.correo).includes(q)):[];
 const promE=sid=>{const ns=S.examenes.filter(e=>g&&e.grupos.includes(g.id)).map(e=>S.intentos[e.id+'|'+sid]).filter(it=>it&&it.nota!=null).map(it=>it.nota);return promedio(ns)};
 return `${hero('Docente','Mis grupos','Cada grupo pertenece a una de sus asignaturas. El estudiante entra con su correo y su código como contraseña.',`<button class="btn pri" data-act="grp-new">${ic('plus','sm')}Crear grupo</button>`,'group')}
 ${gs.length?`<div class="grid2" role="group" aria-label="Grupos">${gs.map((x,i)=>`<button data-act="grp-sel" data-id="${x.id}" aria-pressed="${x.id===S.grupoSel}" style="all:unset;cursor:pointer;background:var(--surface);border:2px solid ${x.id===S.grupoSel?'var(--brand)':'var(--line)'};border-radius:22px;padding:18px;display:flex;gap:14px;align-items:center;box-shadow:var(--shadow)"><span class="avatar" style="width:52px;height:52px;background:${PALHEX[i%PALHEX.length]};font-size:1.05rem;border-radius:16px">${esc(x.codigo)}</span><span style="min-width:0"><b>${esc(x.asig)}</b><br><span class="small muted">Grupo ${esc(x.codigo)} · ${x.est.length} estudiante${x.est.length===1?'':'s'} · ${esc(x.periodo)}</span></span></button>`).join('')}</div>`:''}
 ${g?`<div class="card" style="display:flex;flex-direction:column;gap:16px"><div class="row"><div><h2>${esc(g.asig)} · Grupo ${esc(g.codigo)}</h2><div class="small muted">Periodo ${esc(g.periodo)} · ${g.est.length} estudiantes</div></div><span class="spacer"></span><button class="btn sm ghost danger" data-act="grp-del">${ic('trash','sm')}Eliminar grupo</button><button class="btn" data-act="est-bulk">${ic('upload','sm')}Cargar desde Excel</button><button class="btn pri" data-act="est-new">${ic('plus','sm')}Agregar estudiante</button></div>
 <div style="position:relative"><input type="search" id="f-est" placeholder="Buscar por nombre, código o correo" value="${esc(S.fEst||'')}" aria-label="Buscar estudiantes" style="padding-left:42px"><span style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted)">${ic('search','sm')}</span></div>
 <div class="tbl-wrap" style="box-shadow:none"><table><thead><tr><th>Estudiante</th><th>Código</th><th>Programa</th><th class="num">Semestre</th><th class="num">Promedio</th><th class="num"></th></tr></thead><tbody>${ests.length?ests.map(s=>{const p=promE(s.id);return `<tr><td><div class="person">${avatar(s.nombre)}<div style="min-width:0"><b>${esc(s.nombre)}</b><div class="small muted">${esc(s.correo)}</div></div></div></td><td class="mono">${esc(s.codigo)}</td><td>${esc(s.prog)}<div class="small muted">${esc(s.fac)}</div></td><td class="num">${esc(s.semestre)}.°</td><td class="num">${p!=null?`<b>${nota1(p)}</b> ${lvTag(p)}`:'<span class="muted">—</span>'}</td><td class="num"><button class="btn sm ghost" data-act="est-quitar" data-id="${s.id}">Quitar</button></td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty">${ic('users','lg')}No hay estudiantes${q?' que coincidan':''}. Agréguelos uno por uno o desde Excel.</div></td></tr>`}</tbody></table></div></div>`:`<div class="card empty">${ic('group','lg')}<b>Cree su primer grupo</b><span class="small">Luego agregue a los estudiantes uno por uno o desde Excel.</span><button class="btn pri" data-act="grp-new">${ic('plus','sm')}Crear grupo</button></div>`}`}
function formEstudiante(){const progs=Object.keys(S.FAC).map(f=>`<optgroup label="${esc(f)}">${S.FAC[f].map(p=>`<option ${p===doc().prog?'selected':''}>${esc(p)}</option>`).join('')}</optgroup>`).join('');
 modal({title:'Agregar estudiante',icon:['user','c3'],body:`<form id="fe" class="form-grid" novalidate>
 <label class="field" style="grid-column:1/-1"><span>Nombres y apellidos</span><input type="text" id="fe-nombre"></label>
 <label class="field"><span>Correo institucional</span><input type="email" id="fe-correo" placeholder="nombre@uniguajira.edu.co"></label>
 <label class="field"><span>Código</span><input type="text" inputmode="numeric" id="fe-codigo"><small class="hint">Es su contraseña y no se cambia. De 6 a 15 números.</small></label>
 <label class="field"><span>Programa</span><select id="fe-prog">${progs}</select><small class="hint" id="fe-fac">Facultad: ${esc(facDe(doc().prog)||'')}</small></label>
 <label class="field"><span>Semestre</span><select id="fe-sem">${Array.from({length:12},(_,i)=>`<option>${i+1}</option>`).join('')}</select></label>
 <div id="fe-err" class="issues" role="alert" style="grid-column:1/-1" hidden></div></form>`,foot:`<button class="btn" data-act="close">Cancelar</button><button class="btn pri" data-act="est-save">${ic('plus','sm')}Agregar al grupo</button>`})}
async function guardarEstudiante(btn){const v=k=>$('#fe-'+k).value.trim(),errs=[];
 if(!v('nombre'))errs.push('Escriba nombres y apellidos.');if(!RX_MAIL.test(v('correo')))errs.push('Escriba un correo válido.');if(!/^\d{6,15}$/.test(v('codigo')))errs.push('El código solo lleva números (6 a 15).');
 const x=S.estudiantes.find(z=>z.codigo===v('codigo'));if(x&&norm(x.correo)!==norm(v('correo')))errs.push('Ese código ya está registrado con otro correo.');
 if(errs.length){const b=$('#fe-err');b.innerHTML='<b>Revise estos datos:</b><ul>'+errs.map(e=>`<li>${esc(e)}</li>`).join('')+'</ul>';b.hidden=false;return}
 await ocupado(btn,async()=>{const r=await usuarios({accion:'agregar_estudiantes',grupo_id:S.grupoSel,personas:[{nombres:v('nombre'),email:v('correo'),codigo:v('codigo'),programa:v('prog'),semestre:+v('sem')}]});
  if(r.errores&&r.errores.length){const b=$('#fe-err');b.innerHTML='<b>No se pudo agregar:</b><ul>'+r.errores.map(e=>`<li>${esc(e.error)}</li>`).join('')+'</ul>';b.hidden=false;return}
  closeModal();await refrescar();toast(r.agregados[0]&&r.agregados[0].nuevo?'Estudiante agregado. Entra con su correo y su código.':'El estudiante ya tenía cuenta: se agregó a este grupo')})}
function formGrupo(){const d=doc();modal({title:'Crear grupo',size:'sm',icon:['group','c1'],body:`<form id="fg" class="form-grid" novalidate><label class="field" style="grid-column:1/-1"><span>Asignatura</span><select id="fg-asig">${d.asig.map(a=>`<option>${esc(a)}</option>`).join('')}</select></label>
 <label class="field"><span>Código del grupo</span><input type="text" id="fg-cod" placeholder="01" maxlength="12"></label><label class="field"><span>Periodo</span><input type="text" id="fg-per" value="${esc(S.cfg.periodo)}"></label><p class="err" id="fg-err" hidden style="grid-column:1/-1"></p></form>`,foot:`<button class="btn" data-act="close">Cancelar</button><button class="btn pri" data-act="grp-save">Crear grupo</button>`})}
async function guardarGrupo(btn){const c=$('#fg-cod').value.trim(),a=$('#fg-asig').value,p=$('#fg-per').value.trim(),er=$('#fg-err');
 if(!c||!p){er.textContent='Escriba el código del grupo y el periodo.';er.hidden=false;return}
 if(misGrupos().some(g=>g.asig===a&&g.codigo===c&&g.periodo===p)){er.textContent='Ya tiene ese grupo en esa asignatura y periodo.';er.hidden=false;return}
 await ocupado(btn,async()=>{const g=await q(sb.from('grupos').insert({docente_id:S.yo.id,asignatura:a,codigo:c,periodo:p}).select().single());S.grupoSel=g.id;closeModal();await refrescar();toast('Grupo creado')})}

/* ---------- exámenes ---------- */
function vExamenes(){const f=S.exFiltro,ex=misEx().filter(e=>f==='todos'||estadoExamen(e)===f),cnt=k=>misEx().filter(e=>estadoExamen(e)===k).length;
 return `${hero('Docente','Exámenes','Un examen presentado queda bloqueado para no alterar las notas. Para corregirlo, duplíquelo.',`<button class="btn pri" data-act="ex-new">${ic('plus','sm')}Crear examen</button>`,'exam')}
 <div class="seg" role="group" aria-label="Filtrar exámenes">${[['todos','Todos',misEx().length],['en curso','En curso',cnt('en curso')],['programado','Programados',cnt('programado')],['borrador','Borradores',cnt('borrador')],['cerrado','Cerrados',cnt('cerrado')]].map(([k,l,n])=>`<button data-act="ex-filtro" data-v="${k}" aria-pressed="${f===k}">${l} · ${n}</button>`).join('')}</div>
 <div class="grid2">${ex.map(e=>{const st=estadoExamen(e),lock=bloqueado(e);return ticket(e,`${st==='en curso'?`<button class="btn sm hot" data-act="ex-sala" data-id="${e.id}">${ic('eye','sm')}Sala en vivo</button>`:''}${lock||st==='cerrado'?`<button class="btn sm pri" data-act="ex-res" data-id="${e.id}">${ic('chart','sm')}Resultados</button>`:''}${lock?'':`<button class="btn sm" data-act="ex-edit" data-id="${e.id}">${ic('edit','sm')}Editar</button>`}<button class="btn sm" data-act="ex-dup" data-id="${e.id}">${ic('copy','sm')}Duplicar</button>${lock?'':`<button class="btn sm icon ghost danger" data-act="ex-del" data-id="${e.id}" aria-label="Eliminar examen" title="Eliminar">${ic('trash','sm')}</button>`}`)}).join('')||`<div class="card empty">${ic('exam','lg')}${misEx().length?'No hay exámenes en esta categoría.':'Aún no ha creado exámenes.'}${misEx().length?'':`<button class="btn pri" data-act="ex-new">${ic('plus','sm')}Crear examen</button>`}</div>`}</div>`}
async function duplicarExamen(id){const e=clone(S.examenes.find(x=>x.id===id));
 await ocupado(null,async()=>{await rpc('guardar_examen',{p:{titulo:e.titulo+' (copia)',asignatura:e.asig,instrucciones:e.inst,apertura:'',duracion_min:e.dur,estado:'borrador',grupos:e.grupos.filter(g=>S.grupos.some(x=>x.id===g&&x.asig===e.asig)),preguntas:e.preg.map(aServidor)}});S.exFiltro='todos';closeModal();await refrescar('examenes');toast('Examen duplicado como borrador','copy')})}

/* ---------- banco ---------- */
function vBanco(){const f=S.bFiltro,q=norm(S.fBanco||''),lista=S.banco.filter(b=>(!f||b.tipo===f)&&(!q||norm(b.enun+' '+b.asig).includes(q)));
 return `${hero('Docente','Banco de preguntas','Guarde preguntas con el ícono del banco mientras crea un examen y reutilícelas sin volver a escribirlas.',`<button class="btn pri" data-act="ex-new">${ic('plus','sm')}Crear examen con el banco</button>`,'bank')}
 <div class="row"><div style="position:relative;flex:1 1 280px"><input type="search" id="f-banco" placeholder="Buscar en el banco" value="${esc(S.fBanco||'')}" aria-label="Buscar preguntas" style="padding-left:42px"><span style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted)">${ic('search','sm')}</span></div>
 <div class="seg" role="group" aria-label="Filtrar por tipo">${[['','Todas'],['sel','Selección'],['com','Completar'],['rel','Relacionar']].map(([v,l])=>`<button data-act="b-filtro" data-v="${v}" aria-pressed="${f===v}">${l}</button>`).join('')}</div></div>
 <div class="grid2">${lista.map(b=>`<article class="card ${TIPO[b.tipo][1]}" style="display:flex;flex-direction:column;gap:10px;border-top:5px solid var(--tc)"><div class="row"><span class="tag">${ic(b.tipo,'sm')}${TIPO[b.tipo][0]}</span><span class="chip">${esc(b.asig)}</span><span class="spacer"></span><span class="small muted">Usada ${b.usos} ${b.usos===1?'vez':'veces'}</span></div><p style="font-weight:600">${esc(b.enun)}</p>${(b.imgs||[]).length?`<div class="small muted">${ic('image','sm')} ${b.imgs.length} imagen${b.imgs.length>1?'es':''}</div>`:''}<div class="row" style="margin-top:auto"><button class="btn sm" data-act="b-ver" data-id="${b.id}">${ic('eye','sm')}Vista previa</button><button class="btn sm icon ghost danger" data-act="b-del" data-id="${b.id}" aria-label="Quitar del banco">${ic('trash','sm')}</button></div></article>`).join('')||`<div class="card empty">${ic('bank','lg')}${S.banco.length?'No hay preguntas con ese filtro.':'Su banco está vacío. En el editor de exámenes, use el ícono del banco en cada pregunta para guardarla aquí.'}</div>`}</div>`}
function traerBanco(){const e=S.editor,lista=S.banco.filter(b=>b.asig===e.asig);
 modal({title:'Traer preguntas del banco',icon:['bank','c4'],body:lista.length?`<p class="small muted">Preguntas de ${esc(e.asig)}. Marque las que quiere agregar.</p><ul class="list">${lista.map(b=>`<li><input type="checkbox" data-bk="${b.id}" id="bk-${b.id}" style="width:20px;height:20px;accent-color:var(--brand);flex:none"><label for="bk-${b.id}" style="flex:1;min-width:0;cursor:pointer"><span class="tag ${TIPO[b.tipo][1]}">${TIPO[b.tipo][0]}</span> <span>${esc(b.enun)}</span></label></li>`).join('')}</ul>`:`<div class="empty">${ic('bank','lg')}No tiene preguntas guardadas de ${esc(e.asig)}.</div>`,foot:`<button class="btn" data-act="close">Cancelar</button>${lista.length?`<button class="btn pri" data-act="bk-add">${ic('plus','sm')}Agregar seleccionadas</button>`:''}`})}
const datosPregunta=q=>{const c=clone(q);delete c.id;delete c.asig;delete c.docente;delete c.usos;return c};

/* ---------- editor ---------- */
