 if(id){const e=S.examenes.find(x=>x.id===id);if(bloqueado(e)){modal({title:'Este examen ya fue presentado',size:'sm',icon:['lock','c2'],body:'<p>Para no alterar las notas, un examen presentado no se puede cambiar. Puede duplicarlo y corregir la copia.</p>',foot:`<button class="btn" data-act="close">Cancelar</button><button class="btn pri" data-act="ex-dup" data-id="${id}">${ic('copy','sm')}Duplicar examen</button>`});return}S.editor=clone(e)}
