function actualizarResumen(){const e=S.editor;if(!e||!$('#ed-res'))return;const tot=e.preg.reduce((a,q)=>a+(+q.valor||0),0),c=e.apertura&&+e.dur?addMin(new Date(e.apertura),+e.dur):null,n=t=>e.preg.filter(q=>q.tipo===t).length,imgs=e.preg.reduce((a,q)=>a+(q.imgs||[]).length+(q.optImgs||[]).filter(Boolean).length+(q.parImgs||[]).filter(Boolean).length,0);
 const er=validarEditor(e),chk=[['Título',!!e.titulo.trim()],['Grupo escogido',e.grupos.length>0],['Apertura y duración',!!e.apertura&&+e.dur>=5&&!er.some(x=>x.includes('pasado'))],['Preguntas completas',e.preg.length>0&&!er.some(x=>x.startsWith('Pregunta'))]],listo=chk.filter(x=>x[1]).length;
 $('#ed-res').innerHTML=`<div class="row" style="flex-wrap:nowrap">${ring(listo/4,listo===4?'var(--ok)':'var(--brand)',64,8,listo+'/4')}<div><h3>Resumen</h3><span class="small muted">${listo===4?'Listo para programar':'Faltan '+(4-listo)+' paso'+(4-listo===1?'':'s')}</span></div></div>
 <div class="row" style="gap:6px"><span class="tag ty-sel">${n('sel')} selección</span><span class="tag ty-com">${n('com')} completar</span><span class="tag ty-rel">${n('rel')} relacionar</span></div>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div><div class="small muted">Preguntas</div><b style="font-size:1.5rem">${e.preg.length}</b></div><div><div class="small muted">Puntos</div><b style="font-size:1.5rem">${String(tot).replace('.',',')}</b></div><div><div class="small muted">Duración</div><b>${+e.dur||0} min</b></div><div><div class="small muted">Imágenes</div><b>${imgs}</b></div></div>
 <div><div class="small muted">Termina para todos</div><b>${c?esc(fmt(c)):'—'}</b></div>
 <div style="display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line);padding-top:12px">${chk.map(([l,ok])=>`<div class="check ${ok?'':'no'}">${ic(ok?'checkc':'clock','sm')}<span>${l}</span></div>`).join('')}</div>
 <p class="small muted">Nota de 0,0 a 5,0; aprueba con ${nota1(S.cfg.aprueba)}.</p>`;
 const t=$('#ed-tot');t&&(t.textContent=`${e.preg.length} pregunta${e.preg.length===1?'':'s'} · ${String(tot).replace('.',',')} puntos`)}
function zonaImgs(q,i){const mx=S.cfg.maxImgs;return `<div class="field"><span>Imágenes del enunciado (hasta ${mx})</span>${(q.imgs||[]).length?`<div class="thumbs">${q.imgs.map((src,j)=>`<div class="thumb"><img src="${esc(src)}" alt="Imagen ${j+1} de la pregunta ${i+1}"><button class="z" data-act="zoom" data-src="q${i}-${j}" aria-label="Ampliar imagen ${j+1}"></button><button class="x" data-act="img-del" data-q="${i}" data-j="${j}" aria-label="Quitar imagen ${j+1}">${ic('x','sm')}</button></div>`).join('')}</div>`:''}
 ${(q.imgs||[]).length<mx?`<label class="drop" data-drop="${i}"><span class="chipi c1">${ic('image')}</span><span><b>Arrastre imágenes aquí o toque para elegir</b><br><span class="small muted">JPG, PNG o GIF. Se reducen solas para que carguen rápido.</span></span><input type="file" accept="image/*" multiple data-img="${i}" class="sr"></label>`:''}</div>`}
function vPreguntaEdit(q,i,n){const [tn,tc]=TIPO[q.tipo];let body='';const L='ABCDEF';
 if(q.tipo==='sel')body=`<div class="field"><span>Opciones · marque la correcta con el círculo</span>${q.opts.map((o,j)=>`<div class="opt ${q.ok===j?'is-ok':''}"><input type="radio" name="ok-${q.id}" data-q="${i}" data-okset="${j}" ${q.ok===j?'checked':''} aria-label="Marcar opción ${L[j]} como correcta"><span class="let">${L[j]}</span><input type="text" data-q="${i}" data-opt="${j}" value="${esc(o)}" placeholder="Texto de la opción ${L[j]}" aria-label="Texto de la opción ${L[j]}">
 ${q.optImgs[j]?`<span class="row" style="gap:4px;flex-wrap:nowrap"><img class="mini-img" src="${esc(q.optImgs[j])}" alt="Imagen opción ${L[j]}" data-act="zoom" data-src="o${i}-${j}"><button class="btn sm icon ghost" data-act="optimg-del" data-q="${i}" data-j="${j}" aria-label="Quitar imagen de la opción ${L[j]}">${ic('trash','sm')}</button></span>`:`<label class="btn sm icon ghost" title="Imagen para la opción ${L[j]}" style="cursor:pointer">${ic('image','sm')}<input type="file" accept="image/*" data-optimg="${i}" data-j="${j}" class="sr" aria-label="Imagen para la opción ${L[j]}"></label>`}
 <button class="btn sm icon ghost" data-act="opt-del" data-q="${i}" data-j="${j}" aria-label="Quitar opción ${L[j]}" ${q.opts.length<=2?'aria-disabled="true"':''}>${ic('x','sm')}</button></div>`).join('')}
 ${q.opts.length<6?`<button class="btn sm ghost" data-act="opt-add" data-q="${i}" style="align-self:flex-start">${ic('plus','sm')}Agregar opción</button>`:''}<small class="hint">Una opción puede ser solo imagen: deje el texto vacío y súbala con el ícono de imagen.</small></div>`;
 if(q.tipo==='com')body=`<div class="field"><span>Respuestas válidas</span><div class="row"><input type="text" id="cr-${q.id}" placeholder="Escriba una respuesta y pulse Agregar" style="flex:1 1 200px" aria-label="Nueva respuesta válida"><button class="btn sm" data-act="com-add" data-q="${i}">${ic('plus','sm')}Agregar</button></div><div class="chips">${q.resp.map((r,j)=>`<span class="chip">${esc(r)}<button data-act="com-del" data-q="${i}" data-j="${j}" aria-label="Quitar ${esc(r)}">×</button></span>`).join('')||'<span class="small muted">Aún no hay respuestas.</span>'}</div><small class="hint">Escriba ___ (tres guiones bajos) en el enunciado donde va el espacio. No importan mayúsculas ni tildes.</small></div>`;
 if(q.tipo==='rel')body=`<div class="field"><span>Pares correctos · al estudiante la columna derecha le sale en desorden</span>${q.pares.map((p,j)=>`<div class="pair"><span class="q-n" style="width:28px;height:28px;font-size:.8rem;background:${PCOL[j%PCOL.length]}">${j+1}</span><input type="text" data-q="${i}" data-par="${j}" data-lado="0" value="${esc(p[0])}" placeholder="Elemento" aria-label="Elemento ${j+1}"><span class="arrow">→</span><input type="text" data-q="${i}" data-par="${j}" data-lado="1" value="${esc(p[1])}" placeholder="Pareja" aria-label="Pareja ${j+1}">
 ${q.parImgs[j]?`<span class="row" style="gap:4px;flex-wrap:nowrap"><img class="mini-img" src="${esc(q.parImgs[j])}" alt="Imagen del elemento ${j+1}" data-act="zoom" data-src="p${i}-${j}"><button class="btn sm icon ghost" data-act="parimg-del" data-q="${i}" data-j="${j}" aria-label="Quitar imagen del elemento ${j+1}">${ic('trash','sm')}</button></span>`:`<label class="btn sm icon ghost" title="Imagen para el elemento ${j+1}" style="cursor:pointer">${ic('image','sm')}<input type="file" accept="image/*" data-parimg="${i}" data-j="${j}" class="sr" aria-label="Imagen para el elemento ${j+1}"></label>`}
 <button class="btn sm icon ghost" data-act="par-del" data-q="${i}" data-j="${j}" aria-label="Quitar par ${j+1}" ${q.pares.length<=2?'aria-disabled="true"':''}>${ic('x','sm')}</button></div>`).join('')}
 ${q.pares.length<8?`<button class="btn sm ghost" data-act="par-add" data-q="${i}" style="align-self:flex-start">${ic('plus','sm')}Agregar par</button>`:''}<small class="hint">El elemento de la izquierda puede llevar imagen. Cada par bien unido suma su parte.</small></div>`;
 return `<article class="q ${tc}"><div class="q-h"><span class="q-n">${i+1}</span><span class="tag">${ic(q.tipo,'sm')}${tn}</span><span class="spacer"></span><label class="row small" style="gap:6px;font-weight:700">Valor <input type="number" min="0.5" max="10" step="0.5" value="${q.valor}" data-q="${i}" data-val style="width:78px;min-height:36px"></label>
 <button class="btn sm icon ghost" data-act="q-prev-view" data-q="${i}" aria-label="Vista previa de la pregunta ${i+1}" title="Vista previa">${ic('eye','sm')}</button><button class="btn sm icon ghost" data-act="q-banco" data-q="${i}" aria-label="Guardar la pregunta ${i+1} en el banco" title="Guardar en el banco">${ic('bank','sm')}</button><button class="btn sm icon ghost" data-act="q-up" data-q="${i}" aria-label="Subir pregunta" ${i===0?'aria-disabled="true"':''}>${ic('up','sm')}</button><button class="btn sm icon ghost" data-act="q-down" data-q="${i}" aria-label="Bajar pregunta" ${i===n-1?'aria-disabled="true"':''}>${ic('down','sm')}</button><button class="btn sm icon ghost danger" data-act="q-del" data-q="${i}" aria-label="Eliminar pregunta ${i+1}">${ic('trash','sm')}</button></div>
 <div class="q-b"><label class="field"><span>Enunciado</span><textarea data-q="${i}" data-enun placeholder="${q.tipo==='com'?'Ejemplo: La capital de La Guajira es ___.':'Escriba la pregunta'}">${esc(q.enun)}</textarea></label>${zonaImgs(q,i)}${body}</div></article>`}
function validarEditor(e){const er=[];if(!e.titulo.trim())er.push('Escriba el título del examen.');if(!e.grupos.length)er.push('Escoja al menos un grupo.');if(!e.apertura)er.push('Indique la fecha y hora de apertura.');else if(new Date(e.apertura)<addMin(ahora(),-1))er.push('La apertura no puede quedar en el pasado.');if(!(+e.dur>=5&&+e.dur<=300))er.push('La duración debe estar entre 5 y 300 minutos.');if(!e.preg.length)er.push('Agregue al menos una pregunta.');
 e.preg.forEach((q,i)=>{const n=`Pregunta ${i+1}: `;if(!q.enun.trim())er.push(n+'falta el enunciado.');if(!(+q.valor>0))er.push(n+'el valor debe ser mayor que 0.');
  if(q.tipo==='sel'){if(q.opts.some((o,j)=>!o.trim()&&!q.optImgs[j]))er.push(n+'hay opciones sin texto ni imagen.');const t=q.opts.filter(o=>o.trim()).map(norm);if(new Set(t).size!==t.length)er.push(n+'hay opciones repetidas.')}
  if(q.tipo==='com'){if(!q.enun.includes('___'))er.push(n+'marque el espacio con ___.');if(!q.resp.length)er.push(n+'agregue al menos una respuesta válida.')}
  if(q.tipo==='rel'){if(q.pares.some((p,j)=>(!p[0].trim()&&!q.parImgs[j])||!p[1].trim()))er.push(n+'hay pares incompletos.');const d=q.pares.map(p=>norm(p[1])).filter(Boolean);if(new Set(d).size!==d.length)er.push(n+'hay parejas repetidas en la columna derecha.')}});return er}
async function guardarEditor(m,btn){const e=S.editor;
 if(m==='programar'){const er=validarEditor(e);if(er.length){S.editorErr=er;render();$('.issues').scrollIntoView({behavior:'smooth',block:'center'});return}}
 else if(!e.titulo.trim()){S.editorErr=['Escriba al menos el título para guardar el borrador.'];render();$('.issues').scrollIntoView({block:'center'});return}
 await ocupado(btn,async()=>{
  const p={id:e.id||'',titulo:e.titulo.trim(),asignatura:e.asig,instrucciones:e.inst||'',apertura:e.apertura?new Date(e.apertura).toISOString():'',duracion_min:+e.dur||60,estado:m==='programar'?'programado':'borrador',grupos:e.grupos,preguntas:e.preg.map(aServidor)};
  await rpc('guardar_examen',{p});S.editor=null;S.editorSucio=false;S.exFiltro='todos';await refrescar('examenes');
  toast(m==='programar'?'Examen programado. Los estudiantes ya lo ven en su lista.':'Borrador guardado')})}
async function subirImgs(files,fn){let n=0;for(const f of files){try{toast('Subiendo imagen…','upload');fn(await subirImagen(f));n++}catch(m){toast(mensaje(m),'alert')}}return n}
function vistaPrevia(q){const fake={resp:{},sel:null},qq=q.tipo==='rel'?{...q,...paresVista(q,'vista')}:q;modal({title:'Vista previa del estudiante',icon:['eye','c1'],body:`<div class="qcard ${TIPO[q.tipo][1]}" style="box-shadow:none"><span class="tag" style="align-self:flex-start">${ic(q.tipo,'sm')}${TIPO[q.tipo][0]}</span>${q.tipo==='com'?vCompletar(qq,fake,true):vEnunciado(qq)+vRespuesta(qq,fake,true)}</div><p class="small muted">Así verá la pregunta el estudiante. Las opciones y los pares salen en orden distinto para cada uno.</p>`,foot:'<button class="btn pri" data-act="close">Listo</button>'})}

